func TestMarkdownHasEverySectionAndOneMermaidFence(t *testing.T) {
	r := Build(sampleInput())
	got := Markdown(r)

	for _, want := range []string{
		"# Repo Cartography: repo-cartographer",
		"## Architecture",
		"## Read these first",
		"## Files the agent read",
		"```mermaid",
		"**1.** `cmd/cartographer/main.go` —",
		"- `internal/agent/loop.go`",
		"Generated by Repo Cartographer",
		"`qwen2.5:1.5b`",
		"Ollama",
		"no cloud API calls",
	} {
		if !strings.Contains(got, want) {
			t.Errorf("markdown missing %q:\n%s", want, got)
		}
	}

	if n := strings.Count(got, "```mermaid"); n != 1 {
		t.Fatalf("want exactly 1 mermaid fence, got %d:\n%s", n, got)
	}
	if n := strings.Count(got, "```"); n != 2 {
		t.Fatalf("want exactly 2 fence markers (open+close), got %d:\n%s", n, got)
	}

	// The fenced block must hold the diagram, un-nested and un-fenced.
	start := strings.Index(got, "```mermaid\n") + len("```mermaid\n")
	end := strings.Index(got[start:], "```")
	if end < 0 {
		t.Fatalf("unterminated mermaid fence")
	}
	inner := got[start : start+end]
	if !strings.HasPrefix(inner, headerComment) || !strings.Contains(inner, "graph LR") {
		t.Fatalf("fence does not contain the diagram:\n%q", inner)
	}
	if strings.Contains(inner, "```") {
		t.Fatalf("nested fence inside the mermaid block:\n%q", inner)
	}

	// Numbering must be sequential.
	for i := range r.Starters {
		if !strings.Contains(got, "**"+itoa(i+1)+".** `") {
			t.Errorf("missing ordered entry %d", i+1)
		}
	}
}

func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	var b []byte
	for n > 0 {
		b = append([]byte{byte('0' + n%10)}, b...)
		n /= 10
	}
	return string(b)
}

func TestMarkdownDeterministic(t *testing.T) {
	r := Build(sampleInput())
	first := Markdown(r)
	for i := 0; i < 25; i++ {
		if got := Markdown(r); got != first {
			t.Fatalf("Markdown not deterministic on run %d", i)
		}
	}
}

func TestMarkdownDegradesGracefully(t *testing.T) {
	tests := []struct {
		name  string
		r     contracts.Report
		want  []string
		avoid []string
	}{
		{
			name: "entirely empty",
			r:    contracts.Report{},
			want: []string{
				"# Repo Cartography: this repository",
				"The agent produced no summary for this run.",
				"The agent did not gather enough structure to draw a diagram.",
				"The agent found no files it could confidently recommend",
				"The agent did not open any files during this run.",
				"driven by a local open model via Ollama",
			},
			avoid: []string{"```mermaid"},
		},
		{
			name: "diagram without edges",
			r: contracts.Report{
				RootPath: "/x/solo",
				Diagram:  Mermaid(Input{Files: []contracts.RepoFile{{Path: "a.go"}}}),
				Summary:  "A summary.",
			},
			want:  []string{"No import edges were resolved", "```mermaid"},
			avoid: []string{"did not gather enough structure"},
		},
		{
			name: "starter without a reason",
			r: contracts.Report{
				Starters: []contracts.Finding{{Path: "a.go"}},
			},
			want:  []string{"**1.** `a.go` — recommended by the agent as an early read"},
			avoid: []string{"**1.** `a.go` — \n"},
		},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			got := Markdown(tc.r)
			for _, w := range tc.want {
				if !strings.Contains(got, w) {
					t.Errorf("missing %q:\n%s", w, got)
				}
			}
			for _, a := range tc.avoid {
				if strings.Contains(got, a) {
					t.Errorf("unexpected %q:\n%s", a, got)
				}
			}
			// Every rendering keeps its headings, however empty the report is.
			for _, h := range []string{"## Architecture", "## Read these first", "## Files the agent read"} {
				if !strings.Contains(got, h) {
					t.Errorf("missing heading %q:\n%s", h, got)
				}
			}
		})
	}
}

func TestMarkdownNeutralisesStrayFences(t *testing.T) {
	r := contracts.Report{Diagram: "```mermaid\ngraph LR\n  n1[\"a\"]\n```"}
	got := Markdown(r)
	if n := strings.Count(got, "```"); n != 2 {
		t.Fatalf("stray fences leaked through (%d markers):\n%s", n, got)
	}
	if !strings.Contains(got, "graph LR") {
		t.Fatalf("diagram body lost:\n%s", got)
	}
}

func TestModelFromSummary(t *testing.T) {
	tests := []struct{ in, want string }{
		{summarize(sampleInput()), "qwen2.5:1.5b"},
		{"no model here", ""},
		{"", ""},
		{modelSentinel + "llama3.2:1b` etc", "llama3.2:1b"},
		{modelSentinel + "unterminated", ""},
	}
	for _, tc := range tests {
		if got := modelFromSummary(tc.in); got != tc.want {
			t.Errorf("modelFromSummary(%q) = %q, want %q", tc.in, got, tc.want)
		}
	}
}

func TestWriteCreatesNestedDirsAndRoundTrips(t *testing.T) {
	dir := t.TempDir()
	target := filepath.Join(dir, "out", "nested", "deeper", "cartography.md")

	r := Build(sampleInput())
	if err := Write(target, r); err != nil {
		t.Fatalf("Write: %v", err)
	}

	raw, err := os.ReadFile(target)
	if err != nil {
		t.Fatalf("ReadFile: %v", err)
	}
	if string(raw) != Markdown(r) {
		t.Fatalf("file content does not match Markdown(r)")
	}

	info, err := os.Stat(target)
	if err != nil {
		t.Fatalf("Stat: %v", err)
	}
	if perm := info.Mode().Perm(); perm != 0o644 {
		t.Errorf("mode = %v, want 0644", perm)
	}

	// Overwriting an existing report must work and leave no temp files behind.
	r2 := Build(Input{RootPath: "/tmp/other"})
	if err := Write(target, r2); err != nil {
		t.Fatalf("Write (overwrite): %v", err)
	}
	raw, err = os.ReadFile(target)
	if err != nil {
		t.Fatalf("ReadFile after overwrite: %v", err)
	}
	if string(raw) != Markdown(r2) {
		t.Fatalf("overwrite did not replace the content")
	}
	entries, err := os.ReadDir(filepath.Dir(target))
	if err != nil {
		t.Fatalf("ReadDir: %v", err)
	}
	if len(entries) != 1 {
		names := []string{}
		for _, e := range entries {
			names = append(names, e.Name())
		}
		t.Errorf("want only the report in the directory, got %v", names)
	}
}

func TestWriteRejectsEmptyPath(t *testing.T) {
	if err := Write("   ", contracts.Report{}); err == nil {
		t.Fatalf("want an error for an empty path")
	}
}

func TestWriteToBareFilenameInTempDir(t *testing.T) {
	dir := t.TempDir()
	cwd, err := os.Getwd()
	if err != nil {
		t.Fatalf("Getwd: %v", err)
	}
	if err := os.Chdir(dir); err != nil {
		t.Fatalf("Chdir: %v", err)
	}
	t.Cleanup(func() { _ = os.Chdir(cwd) })

	if err := Write("report.md", Build(sampleInput())); err != nil {
		t.Fatalf("Write: %v", err)
	}
	if _, err := os.Stat(filepath.Join(dir, "report.md")); err != nil {
		t.Fatalf("Stat: %v", err)
	}
}
